const DICT: Record<Lang, Partial<Record<MsgKey, string>>> = { en, hi, mr };

export function translate(lang: Lang, key: MsgKey, vars?: Record<string, string | number>): string {
  const raw = DICT[lang]?.[key] ?? en[key] ?? key;
  return vars ? raw.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? `{${k}}`)) : raw;
}
